:root {
  --paper: #fffaf1;
  --ink: #27221f;
  --muted: #756b63;
  --line: #dfd3c5;
  --sand: #f2e6d5;
  --ember: #bd542f;
  --ember-pale: #fae0d2;
  --charcoal: #37312d;
  --white: #ffffff;
}

.panel {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.panel-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.mark {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 10px;
  background: var(--ember);
  color: var(--white);
  font-size: 15px;
}

.heading {
  flex: 1;
}

.eyebrow {
  margin: 0 0 1px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 19px;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--ember-pale);
  color: var(--ember);
  font-size: 11px;
  font-weight: 700;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 10px 16px;
  background: var(--sand);
}

.metric {
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--paper);
}

.metric-label,
.foot-label {
  display: block;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.metric-value {
  display: block;
  margin-top: 3px;
  font-size: 17px;
  line-height: 1.1;
}

.metric-unit {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.sample-log {
  padding: 12px 16px 10px;
}

.log-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 7px;
}

.log-title {
  margin-bottom: 1px;
  font-size: 14px;
  line-height: 1.15;
}

.log-note {
  margin-bottom: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.readings {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.reading {
  display: grid;
  grid-template-columns: 44px 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-left: 3px solid var(--ember);
  border-radius: 0 7px 7px 0;
  background: var(--sand);
  font-size: 12px;
}

.reading-time {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.reading-name {
  font-weight: 600;
}

.reading-value {
  color: var(--ember);
  font-size: 12px;
}

.panel-footer {
  display: flex;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
  background: var(--charcoal);
  color: var(--white);
}

.foot-item {
  display: flex;
  align-items: center;
  gap: 7px;
}

.panel-footer .foot-label {
  color: var(--sand);
}

.foot-value {
  font-size: 12px;
}

.alert {
  color: var(--ember-pale);
}
